```python
def is_palindrome(str):
    """
    Check if a given string is a palindrome (reversed and same in both directions).

    :param str: The string to check.
    :return: True if the string is a palindrome, False otherwise.
    """
    # Convert the string to lowercase for case-insensitivity
    str = str.lower()

    # Check if the string is empty or contains only whitespace characters
    if not str:
        return True

    # Initialize a counter to count the number of occurrences of each character
    count = {}
    for char in str:
        if char in count:
            count[char] += 1
        else:
            count[char] = 1

    # Check if all characters are equal and return True if they are, False otherwise
    return all(count.values() == len(str))

