function isPrime(n) {
  // Handle cases where n is 1 or 0
  if (n === 1 || n === 0) {
    return false;
  }

  // Initialize the result to true, as we assume n is prime
  let result = true;

  // Iterate through all the numbers from 2 to the square root of n
  for (let i = 2; i * i <= n; i++) {
    // If there is a divisor found, set result to false
    if (n % i === 0) {
      result = false;
      break;
    }
  }

  // If no divisors were found, return true
  return result;
}
