function checkBalancedParentheses(str) {
  // Create a stack to store the opening parentheses.
  const stack = [];

  // Iterate over the string.
  for (let i = 0; i < str.length; i++) {
    // If the current character is an opening parenthesis, push it onto the stack.
    if (str[i] === '(') {
      stack.push(str[i]);
    }

    // If the current character is a closing parenthesis, check if the stack is empty.
    else if (str[i] === ')' && stack.length > 0) {
      // If the stack is empty, the parentheses are balanced.
      stack.pop();
    } else {
      // If the parentheses are not balanced, return false.
      return false;
    }
  }

  // If the stack is empty, the parentheses are balanced.
  return stack.length === 0;
}
```

