function chunkArray(arr, chunkSize) {
  // Create a new array to store the chunks
  const chunks = [];

  // Iterate through the original array
  for (let i = 0; i < arr.length; i++) {
    // Push the current element to the chunks array
    chunks.push(arr[i]);

    // Check if we have reached the end of a chunk
    if (i + 1 === chunkSize) {
      // Push the remaining elements of the chunk to the chunks array
      chunks.push(...arr.slice(i));
      // Reset the start index of the next chunk
      i = i + chunkSize - 1;
    }
  }

  // Return the chunks array
  return chunks;
}
```

