```javascript
function isPrime(n) {
  // Handle cases where n is less than 2
  if (n <= 1) return false;
  // Initialize the result to true
  let result = true;
  // Iterate through all the numbers from 2 to the square root of n
  for (let i = 2; i * i <= n; i++) {
    // If any of the numbers in the range are factors of n, set result to false
    if (n % i === 0) {
      result = false;
      break;
    }
  }
  // If no factors are found, return true
  return result;
}
```

```javascript
function isAnagram(str1, str2) {
  // Convert the strings to lowercase and remove all whitespace.
  str1 = str1.toLowerCase().replace(/\s/g, "");
  str2 = str2.toLowerCase().replace(/\s/g, "");

  // Convert the strings to arrays of characters.
  const arr1 = str1.split("");
  const arr2 = str2.split("");

  // Check if the arrays have the same length.
  if (arr1.length !== arr2.length) {
    return false;
  }

  // Compare the arrays character by character.
  for (let i = 0; i < arr1.length; i++) {
    if (arr1[i] !== arr2[i]) {
      return false;
    }
  }

  // If the arrays have the same length and are equal character by character, they are anagrams.
  return true;
}
```

**Usage:**

```
console.log(isAnagram("listen", "silent")); // true
console.log(isAnagram("hello", "world")); // false

```javascript
function checkBalancedParentheses(str) {
  // Create a stack to store the opening parentheses.
  const stack = [];

  // Iterate through the string.
  for (let i = 0; i < str.length; i++) {
    // If the current character is an opening parenthesis, push it onto the stack.
    if (str[i] === '(') {
      stack.push(str[i]);
    }

    // If the current character is a closing parenthesis, check if the stack is empty.
    else if (str[i] === ')' && stack.length > 0) {
      stack.pop();
    }
  }

  // If the stack is empty, the parentheses are balanced.
  return stack.length === 0;
}
```

**Example Usage:**

```
console.log(checkBalancedParentheses("(()())")); // Output: true
console.log(checkBalancedParentheses("()[)]")); // Output: false
```

**Explanation:**

* The function uses a stack to keep track of the opening parentheses.
* For each character in the string, it adds it to the stack

