function findDuplicates(arr) {
  // Create a new array to store the unique elements
  const unique = [];

  // Iterate through the input array
  for (const item of arr) {
    // Check if the item is already in the unique array
    if (unique.indexOf(item) !== -1) {
      // If it is, add it to the unique array
      unique.push(item);
    } else {
      // If it is not, add it to the unique array
      unique.push(item);
    }
  }

  // Return the unique array
  return unique;
}
```

