def run_length_encoding(text):
  """
  RLE compression of a string.

  Args:
    text: The string to compress.

  Returns:
    The RLE compressed string.
  """

  # Create a dictionary of run lengths and character frequencies.
  run_lengths = {}
  char_counts = {}
  for i, char in enumerate(text):
    if char not in run_lengths:
      run_lengths[char] = 0
    run_lengths[char] += 1
    if char not in char_counts:
      char_counts[char] = 0
    char_counts[char] += 1

  # Sort the characters by run length in descending order.
  sorted_chars = sorted(char for char, count in char_counts.items() if count > 0)

  # Create the compressed string.
  compressed_text = ""
  for char in sorted_chars:
    if char in run_lengths:
      compressed_text += f"{run_lengths[char]}_{char}"
    else:
      compressed_text += char

